UPDATE pets
SET name = #{name},
    birth_year = #{birthYear},
    sex = #{sex},
    size = #{size},
    weight = #{weight},
    is_neutered = #{isNeutered},
    memo = #{memo}
WHERE id = #{petId}
  AND user_id = #{userId}

UPDATE pets
SET deleted_at = CURRENT_TIMESTAMP
WHERE id = #{petId}
  AND user_id = #{userId}
  AND deleted_at IS NULL
